 def transform(grid):
    h, w = len(grid), len(grid[0])
    anchors = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if not anchors:
        return [row[:] for row in grid]
    values = {r: grid[r][0] for r in anchors}
    period = next(p for p in range(1, h + 1)
                  if all(values[a] == values[b] for a in anchors for b in anchors
                         if a < b and (a - b) % p == 0))
    phase_colors = {r % period: values[r] for r in anchors}
    return [[phase_colors[r % period]] * w for r in range(h)]


