 def transform(grid):
    h, w = len(grid), len(grid[0])
    # The markers encode a single periodic diagonal field. Find the smallest
    # affine residue system that assigns the same color to every marker phase.
    for period in range(1, 2 * max(h, w) + 1):
        for slope in range(1, period + 1):
            bands = {}
            valid = True
            for r, row in enumerate(grid):
                for c, value in enumerate(row):
                    if value:
                        phase = (r + slope * c) % period
                        if phase in bands and bands[phase] != value:
                            valid = False
                            break
                        bands[phase] = value
                if not valid:
                    break
            if valid and len(bands) == period:
                return [[bands[(r + slope * c) % period] for c in range(w)]
                        for r in range(h)]
    # Conservative fallback for an incompletely specified pattern.
    return [row[:] for row in grid]

