 from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max((v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for sy in range(h):
        for sx in range(w):
            if grid[sy][sx] != bg or (sy, sx) in seen:
                continue
            q = deque([(sy, sx)])
            seen.add((sy, sx))
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if not edge:
                fill = 2 if len(comp) == 4 else 7
                for y, x in comp:
                    out[y][x] = fill
    return out

