def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bars = [r for r, row in enumerate(grid) if row.count(2) >= 3]
    if len(bars) < 2:
        return out
    top, bottom = min(bars), max(bars)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 6:
                edge = top if r - top <= bottom - r else bottom
                step = 1 if edge > r else -1
                rr = r + step
                while rr != edge:
                    if grid[rr][c] == 5:
                        out[rr][c] = 6
                    rr += step
                out[r][c] = 4
    return out
